target.css:
:root {
  --ink: #20233a;
  --paper: #fffdf7;
  --line: #deddec;
  --lavender: #eeebff;
  --violet: #6b57d8;
  --coral: #f06d66;
  --yellow: #f5bf42;
  --mint: #55bfa4;
  --muted: #74758a;
}

.broadcast {
  box-sizing: border-box;
  width: 490px;
  height: 286px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  padding: 0 13px;
  border-bottom: 2px solid var(--ink);
}

.station, .live, .channel-head, .footer, .listeners, .slot {
  display: flex;
  align-items: center;
}

.station { gap: 7px; }

.frequency {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border-radius: 50%;
  background: var(--violet);
  color: var(--paper);
  font-size: 8px;
  font-weight: 800;
}

.station-name {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.live {
  gap: 5px;
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .6px;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
}

.live time {
  margin-left: 4px;
  padding-left: 9px;
  border-left: 1px solid var(--line);
  color: var(--ink);
  letter-spacing: 0;
}

.content {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  grid-template-rows: 112px 54px;
  gap: 8px 14px;
  height: 190px;
  padding: 10px 13px;
  box-sizing: border-box;
}

.now { min-width: 0; }

.eyebrow {
  margin: 0 0 4px;
  color: var(--violet);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.now h1 {
  margin: 0;
  font-size: 23px;
  font-weight: 800;
  letter-spacing: -1.2px;
  line-height: .88;
}

.host {
  margin: 6px 0 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.host span { color: var(--coral); }

.wave {
  display: flex;
  align-items: center;
  height: 16px;
  gap: 3px;
}

.wave span {
  width: 4px;
  border-radius: 4px;
  background: var(--violet);
}

.wave span:nth-child(1), .wave span:nth-child(10) { height: 5px; }
.wave span:nth-child(2), .wave span:nth-child(9) { height: 10px; }
.wave span:nth-child(3), .wave span:nth-child(8) { height: 15px; }
.wave span:nth-child(4), .wave span:nth-child(7) { height: 8px; background: var(--yellow); }
.wave span:nth-child(5), .wave span:nth-child(6) { height: 18px; background: var(--coral); }

.mix {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--lavender);
}

.channel { min-width: 0; }

.channel-head {
  justify-content: space-between;
  margin-bottom: 5px;
  font-size: 8px;
  font-weight: 800;
}

.channel-head strong {
  color: var(--muted);
  font-size: 8px;
}

.level {
  display: flex;
  align-items: flex-end;
  height: 39px;
  padding: 2px;
  border: 1px solid var(--ink);
  border-radius: 5px;
  background: var(--paper);
}

.fill {
  display: block;
  width: 100%;
  border-radius: 2px;
}

.fill.coral { height: 71%; background: var(--coral); }
.fill.yellow { height: 86%; background: var(--yellow); }
.fill.mint { height: 40%; background: var(--mint); }

.channel > p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .4px;
}

.schedule {
  padding: 8px 10px;
  border-left: 4px solid var(--yellow);
  border-radius: 0 9px 9px 0;
  background: var(--ink);
  color: var(--paper);
}

.schedule .eyebrow {
  margin-bottom: 4px;
  color: var(--yellow);
}

.slot { gap: 8px; }

.slot time {
  color: var(--mint);
  font-size: 11px;
  font-weight: 800;
}

.slot p {
  margin: 0;
  line-height: 1.05;
}

.slot strong, .slot span { display: block; }
.slot strong { font-size: 10px; }
.slot span { margin-top: 2px; color: var(--line); font-size: 8px; }

.footer {
  justify-content: space-between;
  height: 34px;
  padding: 0 13px;
  border-top: 1px solid var(--line);
}

.listeners {
  gap: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.listeners b { color: var(--mint); font-size: 12px; }

.footer button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--violet);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .5px;
}

.footer button span {
  margin-left: 3px;
  font-size: 12px;
}

